 func navLabelForPage(page pageNavInfo) string {
 	// Prefer explicit nav_label from the page — the planner set this
 	// intentionally short for nav display.
-	if page.NavLabel != "" {
-		if len(page.NavLabel) <= 30 {
-			return page.NavLabel
-		}
-		return navSimplifyLabel(page.NavLabel, page.URL)
-	}
+	// The strip is applied to the AUTHORED label only, and deliberately NOT to
+	// the title. `pages.nav_label` is a nav-display field where `Category / Page`
+	// is a convention; a title is prose, where a slash can be part of a word.
+	// The fleet has exactly one title containing a slash and it is the proof:
+	// webdesign.co.uk's `A/B Test Calculator | webdesign.co.uk` would become
+	// "B Test Calculator". (Measured 2026-07-31. Currently unflagged, and at 37
+	// chars it would derive from the URL anyway — so this would have been a
+	// latent mangling, not a live one, which is the kind that ships.)
+	//
+	// This leaves one acknowledged hole, with no live instance: navSimplifyLabel
+	// hands a label back verbatim when it is <=15 chars, so a SHORT slash-bearing
+	// TITLE would still reach a nav row. 0 such rows exist (measured, same day);
+	// tracked in bugs_open/149 A7 rather than fixed by mangling prose.
+	if label := navLabelDropCategoryPrefix(page.NavLabel); label != "" {
+		if len(label) <= 30 {
+			return label
+		}
+		// Passing the STRIPPED label is provably a no-op here: navSimplifyLabel
+		// reads its label argument only in the `len(label) <= 15` early return,
+		// and this line is reachable only when len(label) > 30.
+		return navSimplifyLabel(label, page.URL)
+	}
+	// Reached when there is no authored label, OR when the authored label was
+	// nothing but separators and whitespace ("/", " / ") and so names no page.
 	return navSimplifyLabel(page.Title, page.URL)
 }
+
+// navCategorySeparator matches a "/" acting as a CATEGORY SEPARATOR — one with
+// whitespace beside it, or one at the very start or end of the label. It
+// deliberately does NOT match an intra-word slash such as the "A/B" in
+// "A/B Test Calculator".
+var navCategorySeparator = regexp.MustCompile(`\s+/\s*|\s*/\s+|^\s*/|/\s*$`)
+
+// navLabelDropCategoryPrefix takes the page's own name out of an authored
+// nav_label shaped `Category / Page Name`:
+//
+//	"Tools / AI Readiness Quiz"  -> "AI Readiness Quiz"
+//	"Tools / "                   -> "Tools"      (last segment WITH CONTENT)
+//	"A/B Test Calculator"        -> unchanged    (intra-word, not a separator)
+//	"/"                          -> ""           (names no page; caller uses title)
+//
+// It returns the last non-empty SEGMENT, not the text after the last separator:
+// the earlier form returned the original label when that tail was empty, so
+// "Tools / " survived with its slash and was then trusted verbatim at <=30
+// chars — the invariant held for the common case and called itself a guarantee.
+func navLabelDropCategoryPrefix(label string) string {
+	if !strings.Contains(label, "/") {
+		return label
+	}
+	parts := navCategorySeparator.Split(label, -1)
+	for i := len(parts) - 1; i >= 0; i-- {
+		if seg := strings.TrimSpace(parts[i]); seg != "" {
+			return seg
+		}
+	}
+	return ""
+}

@@ platform/orchestration/actions/nav_membership_test.go
 func TestAuthoredNavLabelNeverKeepsItsCategoryPrefix(t *testing.T) {
 	cases := []struct{ name, navLabel, url, title, want string }{
 		{"ai-readiness-quiz", "Tools / AI Readiness Quiz", "/tools/ai-readiness-quiz.html", "AI Readiness Quiz | Tools", "AI Readiness Quiz"},
 		{"agent-complexity-estimator", "Tools / Agent Architecture Complexity Estimator", "/tools/agent-complexity-estimator.html", "Agent Architecture Complexity Estimator", "Agent Complexity Estimator"},
+		// DEGENERATE SEPARATORS — the branch a reviewer found unexercised, where
+		// the first version returned the ORIGINAL label (slash intact) because the
+		// text after the last "/" was empty, and <=30 chars then trusted it.
+		{"trailing-sep", "Tools / ", "/tools/tool-arena.html", "Arena Interface", "Tools"},
+		{"trailing-sep-nospace", "Tools/", "/tools/tool-arena.html", "Arena Interface", "Tools"},
+		{"leading-sep", "/ Arena", "/tools/tool-arena.html", "Arena Interface", "Arena"},
+		// Nothing but separators names no page: the authored label is abandoned
+		// and the TITLE is used — not the separators, and not "".
+		{"only-seps", "/", "/tools/tool-arena.html", "Arena", "Arena"},
+		{"only-seps-spaced", " / / ", "/tools/tool-arena.html", "Arena", "Arena"},
+		// AN INTRA-WORD SLASH IS PART OF THE NAME. Splitting on any "/" turns this
+		// into "B Test Calculator". webdesign.co.uk really has
+		// tool-ab-test-calculator, titled "A/B Test Calculator | webdesign.co.uk".
+		{"ab-test", "A/B Test Calculator", "/tools/tool-ab-test-calculator.html", "A/B Test Calculator | webdesign.co.uk", "A/B Test Calculator"},
+		// Both together: a real category prefix in front of a name with its own
+		// slash. The prefix goes, the name survives intact.
+		{"ab-test-prefixed", "Tools / A/B Test Calculator", "/tools/tool-ab-test-calculator.html", "A/B Test Calculator | webdesign.co.uk", "A/B Test Calculator"},
 	}
 	for _, tc := range cases {
 		t.Run(tc.name, func(t *testing.T) {
 			got := navLabelForPage(pageNavInfo{Name: tc.name, Title: tc.title, URL: tc.url, NavLabel: tc.navLabel})
-			if strings.Contains(got, "/") {
-				t.Fatalf("... a nav label must never contain a path separator ...", tc.navLabel, got)
-			}
+			// "no CATEGORY SEPARATOR survives", not "no slash survives". The
+			// stronger form would condemn "A/B Test Calculator", where the slash
+			// is part of the name.
+			if navCategorySeparator.MatchString(got) {
+				t.Fatalf("navLabelForPage(nav_label=%q) = %q — a nav label must never keep a category separator; ai-agent-orchestration.com served exactly this", tc.navLabel, got)
+			}
 			if got != tc.want {
 				t.Fatalf("navLabelForPage(nav_label=%q, url=%q) = %q, want %q", tc.navLabel, tc.url, got, tc.want)
 			}
 		})
 	}
 }
